-- 8. OPUS — SAT_COMMON_CONTACT   [Implemented]
-- standard satellite, sat_multi_source; PK PARTY_HKEY; 12 RECORD_SOURCE group(s):
-- OPUS_AZBJ_PARTNER_EXTN [4 col(s)], OPUS_BJAZ_CLM_SUPP_EXTN [4 col(s)],
-- OPUS_BJAZ_CTNGY_GC_MEM_DATA [1 col(s)], OPUS_BJAZ_CTNGY_PA_MEM_DTLS [4 col(s)],
-- OPUS_BJAZ_HM_HOSPITAL_MASTER [4 col(s)], OPUS_BJAZ_HM_MEMBER_DTLS [2 col(s)],
-- OPUS_BJAZ_SH_MEM_DTLS_EXTN [1 col(s)], OPUS_CLM_SUPPLIERS [1 col(s)], OPUS_CP_PARTNERS
-- [3 col(s)], OPUS_BJAZ_T_CKYC_OTP [1 col(s)], OPUS_BJAZ_T_EKYC [1 col(s)],
-- OPUS_BJAZ_T_KYC_DETAILS [1 col(s)]. OBJECT satellite: MOBILENUMBER hold one entry per
-- source table (sat value = col:"<TABLE>"; expected = MAX over that table's RAW rows, as
-- the macro does). Plain columns are MAX across all tables and are not compared per
-- table. A table absent from the latest incremental window is absent from the latest row
-- -- compare after a full load.
----------------------------------------------------------------------------------------
with s2 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_CONTACT
     where RECORD_SOURCE = 'OPUS'
       and (MOBILENUMBER:"BJAZ_CLM_SUPP_EXTN" is not null)
     order by hkey
     limit 100
),
c2 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           MOBILENUMBER:"BJAZ_CLM_SUPP_EXTN"::varchar as MOBILENUMBER
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_CONTACT
     where RECORD_SOURCE = 'OPUS'
       and PARTY_HKEY in (select hkey from s2)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
e2 as (  -- expected value(s) at the latest RAW load timestamp per key
    select hkey, max(MOBILENUMBER) as MOBILENUMBER
      from (
        -- via stg_partner__bjaz_clm_supp_extn
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
               ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
               to_varchar(("SUPP_MOBILE"::number)) as MOBILENUMBER
          from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CLM_SUPP_EXTN
      )
     where hkey in (select hkey from s2) and ldts is not null
     group by hkey
),
r2 as (
    select 'MOBILENUMBER' as column_name, c.hkey, c.MOBILENUMBER as sat_value,
           max(iff(equal_null(c.MOBILENUMBER, e.MOBILENUMBER), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.MOBILENUMBER) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.MOBILENUMBER
),
