           nullif(trim(to_varchar(("DATE_OF_BIRTH"::timestamp_ntz))), '') as dateofbirth,
           nullif(trim(to_varchar(("DATE_OF_DEATH"::timestamp_ntz))), '') as dateofdeath,
           nullif(trim(to_varchar((nullif(trim("FIRST_NAME"::varchar), '')))), '') as firstname,
           nullif(trim(to_varchar((nullif(trim("SEX"::varchar), '')))), '') as gendercode,
           nullif(trim(to_varchar((nullif(trim("SURNAME"::varchar), '')))), '') as lastname,
           nullif(trim(to_varchar((nullif(trim("MIDDLE_NAME"::varchar), '')))), '') as middlename,
           nullif(trim(to_varchar((nullif(trim("AFTER_TITLE"::varchar), '')))), '') as namesuffix,
           nullif(trim(to_varchar((nullif(trim("NATIONALITY"::varchar), '')))), '') as nationality,
           nullif(trim(to_varchar((nullif(trim("NAME"::varchar), '')))), '') as partyfullname,
           nullif(trim(to_varchar((nullif(trim("INSTITUTION_NAME"::varchar), '')))), '') as partylegalname,
           nullif(trim(to_varchar((nullif(trim("SHORT_NAME"::varchar), '')))), '') as partyshortname,
           nullif(trim(to_varchar((nullif(trim("PARTNER_TYPE"::varchar), '')))), '') as partytypecode,
           nullif(trim(to_varchar((nullif(trim("BEFORE_TITLE"::varchar), '')))), '') as salutation,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.CP_PARTNERS
     where (nullif(trim("PART_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PART_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t21 as (  -- stitch source OPUS_OCP_INTERESTED_PARTIES
    select distinct (nullif(trim("PARTNER_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("CUSTOMER_NAME_TEXT"::varchar), '')))), '') as partyfullname,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.OCP_INTERESTED_PARTIES
     where (nullif(trim("PARTNER_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PARTNER_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
k1 as (
    select parent_bk from g1_t0
    union
    select parent_bk from g1_t1
    union
    select parent_bk from g1_t3
    union
    select parent_bk from g1_t5
    union
    select parent_bk from g1_t6
    union
