           g1_t20.partyshortname as partyshortname,
           coalesce(g1_t0.partystatus, g1_t8.partystatus, g1_t10.partystatus, g1_t17.partystatus) as partystatus,
           g1_t20.partytypecode as partytypecode,
           g1_t0.placeofbirth as placeofbirth,
           g1_t20.salutation as salutation,
           array_to_string(array_construct_compact(
               case when g1_t0.parent_bk is not null then 'OPUS_AZBJ_PARTNER_EXTN' end,
               case when g1_t1.parent_bk is not null then 'OPUS_BA_HCP_DT_MEM' end,
               case when g1_t3.parent_bk is not null then 'OPUS_BJAZ_CLM_SUPP_EXTN' end,
               case when g1_t5.parent_bk is not null then 'OPUS_BJAZ_CTNGY_FF_DTLS_EXTN' end,
               case when g1_t6.parent_bk is not null then 'OPUS_BJAZ_CTNGY_GC_MEM_DATA' end,
               case when g1_t7.parent_bk is not null then 'OPUS_BJAZ_CTNGY_PA_MEM_DTLS' end,
               case when g1_t8.parent_bk is not null then 'OPUS_BJAZ_EC_MEM_DTLS_EXTN' end,
