               case when g1_t14.parent_bk is not null then 'OPUS_BJAZ_INTERMEDIARY' end,
               case when g1_t16.parent_bk is not null then 'OPUS_BJAZ_PA_DETL_EXTN' end,
               case when g1_t17.parent_bk is not null then 'OPUS_BJAZ_SH_MEM_DTLS_EXTN' end,
               case when g1_t18.parent_bk is not null then 'OPUS_BJAZ_SPP_MEMBER_DTLS' end,
               case when g1_t19.parent_bk is not null then 'OPUS_BJAZ_STARPKG_FF_DTLS' end,
               case when g1_t20.parent_bk is not null then 'OPUS_CP_PARTNERS' end,
               case when g1_t21.parent_bk is not null then 'OPUS_OCP_INTERESTED_PARTIES' end
           ), ', ') as record_source,
           greatest_ignore_nulls(g1_t0.inc_job_updated_at, g1_t1.inc_job_updated_at, g1_t3.inc_job_updated_at, g1_t5.inc_job_updated_at, g1_t6.inc_job_updated_at, g1_t7.inc_job_updated_at, g1_t8.inc_job_updated_at, g1_t9.inc_job_updated_at, g1_t10.inc_job_updated_at, g1_t11.inc_job_updated_at, g1_t12.inc_job_updated_at, g1_t13.inc_job_updated_at, g1_t14.inc_job_updated_at, g1_t16.inc_job_updated_at, g1_t17.inc_job_updated_at, g1_t18.inc_job_updated_at, g1_t19.inc_job_updated_at, g1_t20.inc_job_updated_at, g1_t21.inc_job_updated_at) as inc_job_updated_at
      from k1 ak
      left join g1_t0 on g1_t0.parent_bk = ak.parent_bk
      left join g1_t1 on g1_t1.parent_bk = ak.parent_bk
      left join g1_t3 on g1_t3.parent_bk = ak.parent_bk
      left join g1_t5 on g1_t5.parent_bk = ak.parent_bk
      left join g1_t6 on g1_t6.parent_bk = ak.parent_bk
      left join g1_t7 on g1_t7.parent_bk = ak.parent_bk
      left join g1_t8 on g1_t8.parent_bk = ak.parent_bk
      left join g1_t9 on g1_t9.parent_bk = ak.parent_bk
      left join g1_t10 on g1_t10.parent_bk = ak.parent_bk
      left join g1_t11 on g1_t11.parent_bk = ak.parent_bk
      left join g1_t12 on g1_t12.parent_bk = ak.parent_bk
      left join g1_t13 on g1_t13.parent_bk = ak.parent_bk
      left join g1_t14 on g1_t14.parent_bk = ak.parent_bk
      left join g1_t16 on g1_t16.parent_bk = ak.parent_bk
      left join g1_t17 on g1_t17.parent_bk = ak.parent_bk
      left join g1_t18 on g1_t18.parent_bk = ak.parent_bk
      left join g1_t19 on g1_t19.parent_bk = ak.parent_bk
      left join g1_t20 on g1_t20.parent_bk = ak.parent_bk
      left join g1_t21 on g1_t21.parent_bk = ak.parent_bk
    qualify row_number() over (partition by ak.parent_bk order by g1_t0.partystatus nulls last, g1_t0.placeofbirth nulls last, g1_t1.partyfullname nulls last, g1_t3.firstname nulls last, g1_t3.lastname nulls last, g1_t3.middlename nulls last, g1_t3.partyfullname nulls last, g1_t3.partylegalname nulls last, g1_t5.dateofbirth nulls last, g1_t5.gendercode nulls last, g1_t5.partyfullname nulls last, g1_t6.age nulls last, g1_t6.dateofbirth nulls last, g1_t6.gendercode nulls last, g1_t6.partyfullname nulls last, g1_t7.age nulls last, g1_t7.dateofbirth nulls last, g1_t7.gendercode nulls last, g1_t7.lastname nulls last, g1_t7.middlename nulls last, g1_t7.partyfullname nulls last, g1_t8.age nulls last, g1_t8.dateofbirth nulls last, g1_t8.gendercode nulls last, g1_t8.partyfullname nulls last, g1_t8.partystatus nulls last, g1_t9.age nulls last, g1_t9.dateofbirth nulls last, g1_t9.gendercode nulls last, g1_t9.partyfullname nulls last, g1_t9.partylegalname nulls last, g1_t10.age nulls last, g1_t10.dateofbirth nulls last, g1_t10.gendercode nulls last, g1_t10.partyfullname nulls last, g1_t10.partystatus nulls last, g1_t11.age nulls last, g1_t11.dateofbirth nulls last, g1_t11.gendercode nulls last, g1_t11.partyfullname nulls last, g1_t12.partydisplayname nulls last, g1_t12.partyfullname nulls last, g1_t13.age nulls last, g1_t13.dateofbirth nulls last, g1_t13.gendercode nulls last, g1_t13.partyfullname nulls last, g1_t14.partyfullname nulls last, g1_t16.age nulls last, g1_t16.dateofbirth nulls last, g1_t16.partyfullname nulls last, g1_t17.age nulls last, g1_t17.dateofbirth nulls last, g1_t17.gendercode nulls last, g1_t17.partyfullname nulls last, g1_t17.partylegalname nulls last, g1_t17.partystatus nulls last, g1_t18.age nulls last, g1_t18.dateofbirth nulls last, g1_t18.gendercode nulls last, g1_t18.partyfullname nulls last, g1_t18.partylegalname nulls last, g1_t19.age nulls last, g1_t19.dateofbirth nulls last, g1_t19.gendercode nulls last, g1_t19.partyfullname nulls last, g1_t20.dateofbirth nulls last, g1_t20.dateofdeath nulls last, g1_t20.firstname nulls last, g1_t20.gendercode nulls last, g1_t20.lastname nulls last, g1_t20.middlename nulls last, g1_t20.namesuffix nulls last, g1_t20.nationality nulls last, g1_t20.partyfullname nulls last, g1_t20.partylegalname nulls last, g1_t20.partyshortname nulls last, g1_t20.partytypecode nulls last, g1_t20.salutation nulls last, g1_t21.partyfullname nulls last) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stitch_party_identity
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || st.parent_bk AS VARCHAR))), '')) as hkey,
               st.inc_job_updated_at as ldts,
               to_varchar(st.age) as AGE,
               to_varchar(st.dateofbirth) as DATEOFBIRTH,
               to_varchar(st.dateofdeath) as DATEOFDEATH,
               to_varchar(st.firstname) as FIRSTNAME,
               to_varchar(st.gendercode) as GENDERCODE,
               to_varchar(st.lastname) as LASTNAME,
               to_varchar(st.middlename) as MIDDLENAME,
               to_varchar(st.namesuffix) as NAMESUFFIX,
               to_varchar(st.nationality) as NATIONALITY,
               to_varchar(st.partydisplayname) as PARTYDISPLAYNAME,
               to_varchar(st.partyfullname) as PARTYFULLNAME,
               to_varchar(st.partylegalname) as PARTYLEGALNAME,
               to_varchar(st.partyshortname) as PARTYSHORTNAME,
               to_varchar(st.partystatus) as PARTYSTATUS,
               to_varchar(st.partytypecode) as PARTYTYPECODE,
               to_varchar(st.placeofbirth) as PLACEOFBIRTH,
               to_varchar(st.salutation) as SALUTATION,
               st.record_source as RECORD_SOURCE
          from st1 st
      )
     where (hkey, ldts) in (select hkey, LOAD_DATETIME from c1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'AGE' as column_name, c.hkey, c.AGE as sat_value,
           max(iff(equal_null(c.AGE, e.AGE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.AGE) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.AGE
    union all
    select 'DATEOFBIRTH' as column_name, c.hkey, c.DATEOFBIRTH as sat_value,
           max(iff(equal_null(c.DATEOFBIRTH, e.DATEOFBIRTH), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.DATEOFBIRTH) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.DATEOFBIRTH
    union all
    select 'DATEOFDEATH' as column_name, c.hkey, c.DATEOFDEATH as sat_value,
           max(iff(equal_null(c.DATEOFDEATH, e.DATEOFDEATH), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.DATEOFDEATH) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.DATEOFDEATH
    union all
    select 'FIRSTNAME' as column_name, c.hkey, c.FIRSTNAME as sat_value,
           max(iff(equal_null(c.FIRSTNAME, e.FIRSTNAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.FIRSTNAME) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.FIRSTNAME
    union all
    select 'GENDERCODE' as column_name, c.hkey, c.GENDERCODE as sat_value,
           max(iff(equal_null(c.GENDERCODE, e.GENDERCODE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.GENDERCODE) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.GENDERCODE
    union all
    select 'LASTNAME' as column_name, c.hkey, c.LASTNAME as sat_value,
           max(iff(equal_null(c.LASTNAME, e.LASTNAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.LASTNAME) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.LASTNAME
    union all
    select 'MIDDLENAME' as column_name, c.hkey, c.MIDDLENAME as sat_value,
           max(iff(equal_null(c.MIDDLENAME, e.MIDDLENAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.MIDDLENAME) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.MIDDLENAME
    union all
    select 'NAMESUFFIX' as column_name, c.hkey, c.NAMESUFFIX as sat_value,
           max(iff(equal_null(c.NAMESUFFIX, e.NAMESUFFIX), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.NAMESUFFIX) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.NAMESUFFIX
    union all
    select 'NATIONALITY' as column_name, c.hkey, c.NATIONALITY as sat_value,
           max(iff(equal_null(c.NATIONALITY, e.NATIONALITY), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.NATIONALITY) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.NATIONALITY
    union all
    select 'PARTYDISPLAYNAME' as column_name, c.hkey, c.PARTYDISPLAYNAME as sat_value,
           max(iff(equal_null(c.PARTYDISPLAYNAME, e.PARTYDISPLAYNAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.PARTYDISPLAYNAME) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.PARTYDISPLAYNAME
    union all
    select 'PARTYFULLNAME' as column_name, c.hkey, c.PARTYFULLNAME as sat_value,
           max(iff(equal_null(c.PARTYFULLNAME, e.PARTYFULLNAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.PARTYFULLNAME) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.PARTYFULLNAME
    union all
    select 'PARTYLEGALNAME' as column_name, c.hkey, c.PARTYLEGALNAME as sat_value,
           max(iff(equal_null(c.PARTYLEGALNAME, e.PARTYLEGALNAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.PARTYLEGALNAME) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.PARTYLEGALNAME
    union all
    select 'PARTYSHORTNAME' as column_name, c.hkey, c.PARTYSHORTNAME as sat_value,
           max(iff(equal_null(c.PARTYSHORTNAME, e.PARTYSHORTNAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.PARTYSHORTNAME) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.PARTYSHORTNAME
    union all
    select 'PARTYSTATUS' as column_name, c.hkey, c.PARTYSTATUS as sat_value,
           max(iff(equal_null(c.PARTYSTATUS, e.PARTYSTATUS), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.PARTYSTATUS) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.PARTYSTATUS
    union all
    select 'PARTYTYPECODE' as column_name, c.hkey, c.PARTYTYPECODE as sat_value,
           max(iff(equal_null(c.PARTYTYPECODE, e.PARTYTYPECODE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.PARTYTYPECODE) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.PARTYTYPECODE
    union all
    select 'PLACEOFBIRTH' as column_name, c.hkey, c.PLACEOFBIRTH as sat_value,
           max(iff(equal_null(c.PLACEOFBIRTH, e.PLACEOFBIRTH), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.PLACEOFBIRTH) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.PLACEOFBIRTH
    union all
    select 'SALUTATION' as column_name, c.hkey, c.SALUTATION as sat_value,
           max(iff(equal_null(c.SALUTATION, e.SALUTATION), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.SALUTATION) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.SALUTATION
    union all
    select 'RECORD_SOURCE' as column_name, c.hkey, c.RECORD_SOURCE as sat_value,
           max(iff(equal_null(c.RECORD_SOURCE, e.RECORD_SOURCE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.RECORD_SOURCE) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.RECORD_SOURCE
),
s2 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY
     where RECORD_SOURCE = 'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS'
     order by hkey
     limit 100
),
c2 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(DATEOFBIRTH) as DATEOFBIRTH,
           to_varchar(FIRSTNAME) as FIRSTNAME,
           to_varchar(GENDERCODE) as GENDERCODE,
           to_varchar(LASTNAME) as LASTNAME,
           to_varchar(MIDDLENAME) as MIDDLENAME,
           to_varchar(NATIONALITY) as NATIONALITY,
           to_varchar(PARTYFULLNAME) as PARTYFULLNAME,
           to_varchar(PLACEOFBIRTH) as PLACEOFBIRTH,
           to_varchar(SALUTATION) as SALUTATION
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY
     where RECORD_SOURCE = 'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS'
       and PARTY_HKEY in (select hkey from s2)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
e2 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
