           max(iff(equal_null(c.GENDERCODE, e.GENDERCODE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.GENDERCODE) as src_value
      from c8 c left join e8 e on e.hkey = c.hkey
     group by c.hkey, c.GENDERCODE
    union all
    select 'PARTYFULLNAME' as column_name, c.hkey, c.PARTYFULLNAME as sat_value,
           max(iff(equal_null(c.PARTYFULLNAME, e.PARTYFULLNAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.PARTYFULLNAME) as src_value
      from c8 c left join e8 e on e.hkey = c.hkey
     group by c.hkey, c.PARTYFULLNAME
    union all
    select 'PARTYTYPECODE' as column_name, c.hkey, c.PARTYTYPECODE as sat_value,
           max(iff(equal_null(c.PARTYTYPECODE, e.PARTYTYPECODE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.PARTYTYPECODE) as src_value
      from c8 c left join e8 e on e.hkey = c.hkey
     group by c.hkey, c.PARTYTYPECODE
),
s9 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY
     where RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_OCR'
     order by hkey
     limit 100
),
c9 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(DATEOFBIRTH) as DATEOFBIRTH,
           to_varchar(GENDERCODE) as GENDERCODE,
           to_varchar(LASTNAME) as LASTNAME,
           to_varchar(NATIONALITY) as NATIONALITY,
           to_varchar(PLACEOFBIRTH) as PLACEOFBIRTH
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY
     where RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_OCR'
       and PARTY_HKEY in (select hkey from s9)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
e9 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_partner__bjaz_t_kyc_ocr
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(upper(trim(coalesce((nullif(trim("FIELD_TYPE"::varchar), '')),''))) || ':' || upper(trim(coalesce((nullif(trim("FIELD_VALUE"::varchar), '')),''))), ':')) AS VARCHAR))), '')) as hkey,
               (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as ldts,
               to_varchar((nullif(trim("DOB"::varchar), ''))) as DATEOFBIRTH,
               to_varchar((nullif(trim("GENDER"::varchar), ''))) as GENDERCODE,
               to_varchar((nullif(trim("SURNAME"::varchar), ''))) as LASTNAME,
               to_varchar((nullif(trim("NATIONALITY"::varchar), ''))) as NATIONALITY,
               to_varchar((nullif(trim("PLACE_OF_BIRTH"::varchar), ''))) as PLACEOFBIRTH
          from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_OCR
      )
     where hkey in (select hkey from s9) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r9 as (
    select 'DATEOFBIRTH' as column_name, c.hkey, c.DATEOFBIRTH as sat_value,
           max(iff(equal_null(c.DATEOFBIRTH, e.DATEOFBIRTH), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.DATEOFBIRTH) as src_value
      from c9 c left join e9 e on e.hkey = c.hkey
     group by c.hkey, c.DATEOFBIRTH
    union all
    select 'GENDERCODE' as column_name, c.hkey, c.GENDERCODE as sat_value,
           max(iff(equal_null(c.GENDERCODE, e.GENDERCODE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.GENDERCODE) as src_value
      from c9 c left join e9 e on e.hkey = c.hkey
     group by c.hkey, c.GENDERCODE
    union all
    select 'LASTNAME' as column_name, c.hkey, c.LASTNAME as sat_value,
           max(iff(equal_null(c.LASTNAME, e.LASTNAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.LASTNAME) as src_value
      from c9 c left join e9 e on e.hkey = c.hkey
     group by c.hkey, c.LASTNAME
    union all
    select 'NATIONALITY' as column_name, c.hkey, c.NATIONALITY as sat_value,
           max(iff(equal_null(c.NATIONALITY, e.NATIONALITY), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.NATIONALITY) as src_value
      from c9 c left join e9 e on e.hkey = c.hkey
     group by c.hkey, c.NATIONALITY
    union all
    select 'PLACEOFBIRTH' as column_name, c.hkey, c.PLACEOFBIRTH as sat_value,
           max(iff(equal_null(c.PLACEOFBIRTH, e.PLACEOFBIRTH), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.PLACEOFBIRTH) as src_value
      from c9 c left join e9 e on e.hkey = c.hkey
     group by c.hkey, c.PLACEOFBIRTH
)
select 'OPUS' as project, 'SAT_PARTY_IDENTITY' as satellite, 'stitch_party_identity (19 tables)' as record_source, column_name,
