----------------------------------------------------------------------------------------
-- 29. OPUS — SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS   [Implemented]
-- standard satellite, sat_multi_source; PK PARTY_HKEY; 3 RECORD_SOURCE group(s):
-- stitch_party_individual_demographics (8 tables) [10 col(s)],
-- OPUS_BJAZ_T_CKYC_PERSONAL_DTLS [3 col(s)], OPUS_BJAZ_T_KYC_OCR [1 col(s)]. Stitch
-- groups: expected values are the stitch view recomputed from RAW (same coalesce
-- priority and tie-break), and RECORD_SOURCE (contributing tables) is compared too.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS
     where regexp_like(RECORD_SOURCE, '^(OPUS_AZBJ_PARTNER_EXTN|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS|OPUS_CP_PARTNERS)(, (OPUS_AZBJ_PARTNER_EXTN|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS|OPUS_CP_PARTNERS))*$')
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(ANNUALHOUSEHOLDINCOME) as ANNUALHOUSEHOLDINCOME,
           to_varchar(ANNUALINCOME) as ANNUALINCOME,
           to_varchar(DESIGNATION) as DESIGNATION,
           to_varchar(EDUCATIONALQUALIFICATION) as EDUCATIONALQUALIFICATION,
           to_varchar(FATHERNAME) as FATHERNAME,
           to_varchar(MARITALSTATUS) as MARITALSTATUS,
           to_varchar(NUMBEROFCHILDREN) as NUMBEROFCHILDREN,
           to_varchar(OCCUPATIONCODE) as OCCUPATIONCODE,
           to_varchar(OCCUPATIONDESCRIPTION) as OCCUPATIONDESCRIPTION,
           to_varchar(SPOUSENAME) as SPOUSENAME,
           RECORD_SOURCE as RECORD_SOURCE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS
     where regexp_like(RECORD_SOURCE, '^(OPUS_AZBJ_PARTNER_EXTN|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS|OPUS_CP_PARTNERS)(, (OPUS_AZBJ_PARTNER_EXTN|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS|OPUS_CP_PARTNERS))*$')
       and PARTY_HKEY in (select hkey from s1)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
g1_t0 as (  -- stitch source OPUS_AZBJ_PARTNER_EXTN
    select distinct (nullif(trim("PART_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("FAMILY_MONTHLY_INCOME"::varchar), '')))), '') as annualhouseholdincome,
           nullif(trim(to_varchar((nullif(trim("EDUCATION"::varchar), '')))), '') as educationalqualification,
           nullif(trim(to_varchar((nullif(trim("FATHER_NAME"::varchar), '')))), '') as fathername,
           nullif(trim(to_varchar(("NO_OF_CHILDREN"::number))), '') as numberofchildren,
           nullif(trim(to_varchar((nullif(trim("OCCUPATION_DESC_GEN"::varchar), '')))), '') as occupationdescription,
           nullif(trim(to_varchar((nullif(trim("SPOUSE_NAME"::varchar), '')))), '') as spousename,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN
     where (nullif(trim("PART_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PART_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t3 as (  -- stitch source OPUS_BJAZ_EC_MEM_DTLS_EXTN
    select distinct (nullif(trim("PARTNER_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar(("GROSS_INCOME"::number))), '') as annualincome,
           nullif(trim(to_varchar((nullif(trim("OCCUPATION"::varchar), '')))), '') as occupationcode,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN
     where (nullif(trim("PARTNER_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PARTNER_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t4 as (  -- stitch source OPUS_BJAZ_HCF_MEMBER_DTLS
    select distinct (nullif(trim("PARTNER_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar(("MONTHLY_INCOME"::number))), '') as annualincome,
           nullif(trim(to_varchar((nullif(trim("MEMBER_OCCUPATION"::varchar), '')))), '') as occupationcode,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HCF_MEMBER_DTLS
     where (nullif(trim("PARTNER_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PARTNER_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t5 as (  -- stitch source OPUS_BJAZ_HC_PART_EXTN
    select distinct (nullif(trim("PART_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("OCCUPATION"::varchar), '')))), '') as occupationcode,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HC_PART_EXTN
     where (nullif(trim("PART_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PART_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t6 as (  -- stitch source OPUS_BJAZ_HM_MEMBER_DTLS
    select distinct (nullif(trim("PARTNER_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar(("GROSS_INCOME"::number))), '') as annualincome,
           nullif(trim(to_varchar((nullif(trim("DESIGNATION"::varchar), '')))), '') as designation,
           nullif(trim(to_varchar((nullif(trim("OCCUPATION"::varchar), '')))), '') as occupationcode,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS
     where (nullif(trim("PARTNER_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PARTNER_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t7 as (  -- stitch source OPUS_BJAZ_SH_MEM_DTLS_EXTN
    select distinct (nullif(trim("PARTNER_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar(("GROSS_INCOME"::number))), '') as annualincome,
           nullif(trim(to_varchar((nullif(trim("OCCUPATION"::varchar), '')))), '') as occupationcode,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN
     where (nullif(trim("PARTNER_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PARTNER_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t8 as (  -- stitch source OPUS_BJAZ_SPP_MEMBER_DTLS
    select distinct (nullif(trim("PARTNER_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("MEMBER_OCCUPATION"::varchar), '')))), '') as occupationcode,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS
     where (nullif(trim("PARTNER_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PARTNER_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t9 as (  -- stitch source OPUS_CP_PARTNERS
    select distinct (nullif(trim("PART_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("MARITAL_STATUS"::varchar), '')))), '') as maritalstatus,
           nullif(trim(to_varchar((nullif(trim("OCCUPATION"::varchar), '')))), '') as occupationcode,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.CP_PARTNERS
     where (nullif(trim("PART_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PART_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
k1 as (
    select parent_bk from g1_t0
    union
    select parent_bk from g1_t3
    union
    select parent_bk from g1_t4
    union
    select parent_bk from g1_t5
    union
    select parent_bk from g1_t6
    union
    select parent_bk from g1_t7
    union
    select parent_bk from g1_t8
    union
    select parent_bk from g1_t9
),
st1 as (  -- stitch_party_individual_demographics recomputed from RAW (same coalesce / priority as the stitch macro)
    select ak.parent_bk,
           g1_t0.annualhouseholdincome as annualhouseholdincome,
           coalesce(g1_t3.annualincome, g1_t4.annualincome, g1_t6.annualincome, g1_t7.annualincome) as annualincome,
           g1_t6.designation as designation,
           g1_t0.educationalqualification as educationalqualification,
           g1_t0.fathername as fathername,
           g1_t9.maritalstatus as maritalstatus,
           g1_t0.numberofchildren as numberofchildren,
           coalesce(g1_t3.occupationcode, g1_t4.occupationcode, g1_t5.occupationcode, g1_t6.occupationcode, g1_t7.occupationcode, g1_t8.occupationcode, g1_t9.occupationcode) as occupationcode,
           g1_t0.occupationdescription as occupationdescription,
           g1_t0.spousename as spousename,
           array_to_string(array_construct_compact(
               case when g1_t0.parent_bk is not null then 'OPUS_AZBJ_PARTNER_EXTN' end,
               case when g1_t3.parent_bk is not null then 'OPUS_BJAZ_EC_MEM_DTLS_EXTN' end,
               case when g1_t4.parent_bk is not null then 'OPUS_BJAZ_HCF_MEMBER_DTLS' end,
               case when g1_t5.parent_bk is not null then 'OPUS_BJAZ_HC_PART_EXTN' end,
               case when g1_t6.parent_bk is not null then 'OPUS_BJAZ_HM_MEMBER_DTLS' end,
               case when g1_t7.parent_bk is not null then 'OPUS_BJAZ_SH_MEM_DTLS_EXTN' end,
               case when g1_t8.parent_bk is not null then 'OPUS_BJAZ_SPP_MEMBER_DTLS' end,
               case when g1_t9.parent_bk is not null then 'OPUS_CP_PARTNERS' end
           ), ', ') as record_source,
           greatest_ignore_nulls(g1_t0.inc_job_updated_at, g1_t3.inc_job_updated_at, g1_t4.inc_job_updated_at, g1_t5.inc_job_updated_at, g1_t6.inc_job_updated_at, g1_t7.inc_job_updated_at, g1_t8.inc_job_updated_at, g1_t9.inc_job_updated_at) as inc_job_updated_at
      from k1 ak
      left join g1_t0 on g1_t0.parent_bk = ak.parent_bk
      left join g1_t3 on g1_t3.parent_bk = ak.parent_bk
      left join g1_t4 on g1_t4.parent_bk = ak.parent_bk
      left join g1_t5 on g1_t5.parent_bk = ak.parent_bk
      left join g1_t6 on g1_t6.parent_bk = ak.parent_bk
      left join g1_t7 on g1_t7.parent_bk = ak.parent_bk
      left join g1_t8 on g1_t8.parent_bk = ak.parent_bk
      left join g1_t9 on g1_t9.parent_bk = ak.parent_bk
    qualify row_number() over (partition by ak.parent_bk order by g1_t0.annualhouseholdincome nulls last, g1_t0.educationalqualification nulls last, g1_t0.fathername nulls last, g1_t0.numberofchildren nulls last, g1_t0.occupationdescription nulls last, g1_t0.spousename nulls last, g1_t3.annualincome nulls last, g1_t3.occupationcode nulls last, g1_t4.annualincome nulls last, g1_t4.occupationcode nulls last, g1_t5.occupationcode nulls last, g1_t6.annualincome nulls last, g1_t6.designation nulls last, g1_t6.occupationcode nulls last, g1_t7.annualincome nulls last, g1_t7.occupationcode nulls last, g1_t8.occupationcode nulls last, g1_t9.maritalstatus nulls last, g1_t9.occupationcode nulls last) = 1
