    select 'KYCCOMPLETIONDATE' as column_name, c.hkey, c.KYCCOMPLETIONDATE as sat_value,
           max(iff(equal_null(c.KYCCOMPLETIONDATE, e.KYCCOMPLETIONDATE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.KYCCOMPLETIONDATE) as src_value
      from c3 c left join e3 e on e.hkey = c.hkey
     group by c.hkey, c.KYCCOMPLETIONDATE
    union all
    select 'LASTKYCREVIEWDATE' as column_name, c.hkey, c.LASTKYCREVIEWDATE as sat_value,
           max(iff(equal_null(c.LASTKYCREVIEWDATE, e.LASTKYCREVIEWDATE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.LASTKYCREVIEWDATE) as src_value
      from c3 c left join e3 e on e.hkey = c.hkey
     group by c.hkey, c.LASTKYCREVIEWDATE
),
s4 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_KYC
     where RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_DETAILS'
     order by hkey
     limit 100
),
c4 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(KYCCOMPLETIONDATE) as KYCCOMPLETIONDATE,
           to_varchar(KYCSTATUS) as KYCSTATUS
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_KYC
     where RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_DETAILS'
       and PARTY_HKEY in (select hkey from s4)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
e4 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_partner__bjaz_t_kyc_details
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(upper(trim(coalesce((nullif(trim("CATEGORY"::varchar), '')),''))) || ':' || upper(trim(coalesce((nullif(trim("INPUT"::varchar), '')),''))), ':')) AS VARCHAR))), '')) as hkey,
               (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as ldts,
               to_varchar((nullif(trim("KYC_DATE"::varchar), ''))) as KYCCOMPLETIONDATE,
               to_varchar((nullif(trim("KYC_STATUS"::varchar), ''))) as KYCSTATUS
          from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_DETAILS
      )
     where hkey in (select hkey from s4) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r4 as (
    select 'KYCCOMPLETIONDATE' as column_name, c.hkey, c.KYCCOMPLETIONDATE as sat_value,
           max(iff(equal_null(c.KYCCOMPLETIONDATE, e.KYCCOMPLETIONDATE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.KYCCOMPLETIONDATE) as src_value
      from c4 c left join e4 e on e.hkey = c.hkey
     group by c.hkey, c.KYCCOMPLETIONDATE
    union all
    select 'KYCSTATUS' as column_name, c.hkey, c.KYCSTATUS as sat_value,
           max(iff(equal_null(c.KYCSTATUS, e.KYCSTATUS), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.KYCSTATUS) as src_value
      from c4 c left join e4 e on e.hkey = c.hkey
     group by c.hkey, c.KYCSTATUS
),
s5 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_KYC
     where RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_INCOMING'
     order by hkey
     limit 100
),
c5 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(KYCMODE) as KYCMODE,
           to_varchar(KYCTYPE) as KYCTYPE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_KYC
     where RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_INCOMING'
       and PARTY_HKEY in (select hkey from s5)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
e5 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_partner__bjaz_t_kyc_incoming
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(upper(trim(coalesce((nullif(trim("SEARCH_CATEGORY"::varchar), '')),''))) || ':' || upper(trim(coalesce((nullif(trim("SEARCH_INPUT"::varchar), '')),''))), ':')) AS VARCHAR))), '')) as hkey,
               (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as ldts,
               to_varchar((nullif(trim("KYC_MODE"::varchar), ''))) as KYCMODE,
               to_varchar((nullif(trim("KYC_TYPE"::varchar), ''))) as KYCTYPE
          from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_INCOMING
      )
     where hkey in (select hkey from s5) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r5 as (
    select 'KYCMODE' as column_name, c.hkey, c.KYCMODE as sat_value,
           max(iff(equal_null(c.KYCMODE, e.KYCMODE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.KYCMODE) as src_value
      from c5 c left join e5 e on e.hkey = c.hkey
     group by c.hkey, c.KYCMODE
    union all
    select 'KYCTYPE' as column_name, c.hkey, c.KYCTYPE as sat_value,
           max(iff(equal_null(c.KYCTYPE, e.KYCTYPE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.KYCTYPE) as src_value
      from c5 c left join e5 e on e.hkey = c.hkey
     group by c.hkey, c.KYCTYPE
)
select 'OPUS' as project, 'SAT_PARTY_KYC' as satellite, 'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS' as record_source, column_name,
       count(*) as keys_compared,
       count_if(src_rows > 0 and matched = 1) as matched,
       count_if(src_rows > 0 and matched = 0) as mismatched,
       count_if(src_rows = 0) as no_source_row,
       array_slice(array_agg(iff(src_rows > 0 and matched = 0, object_construct('hkey', to_varchar(hkey, 'HEX'), 'sat', sat_value, 'src', src_value), null))
                   within group (order by hkey), 0, 3) as mismatch_examples,
       iff(mismatched = 0 and no_source_row = 0, 'PASS', 'FAIL') as status
  from r1
 group by column_name
union all
select 'OPUS' as project, 'SAT_PARTY_KYC' as satellite, 'OPUS_BJAZ_T_CKYC_REL_PERSION_DTLS' as record_source, column_name,
       count(*) as keys_compared,
       count_if(src_rows > 0 and matched = 1) as matched,
