-- 31. OPUS — SAT_PARTY_KYC_REFERENCE   [Implemented]
-- standard satellite, sat_multi_source; PK PARTY_HKEY; 4 RECORD_SOURCE group(s):
-- OPUS_CP_PARTNERS [1 col(s)], OPUS_BJAZ_T_CKYC_OTP [0 col(s)], OPUS_BJAZ_T_CKYC_SEARCH
-- [0 col(s)], OPUS_BJAZ_T_CKYC_REL_PERSION_DTLS [0 col(s)].
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_KYC_REFERENCE
     where RECORD_SOURCE = 'OPUS_CP_PARTNERS'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(KYCREFERENCETYPE) as KYCREFERENCETYPE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_KYC_REFERENCE
     where RECORD_SOURCE = 'OPUS_CP_PARTNERS'
       and PARTY_HKEY in (select hkey from s1)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_partner__cp_partners
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
               ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
               to_varchar((nullif(trim("EVID_TYPE"::varchar), ''))) as KYCREFERENCETYPE
          from BAGIC_PREPROD_CURATED_DB.UTILS.CP_PARTNERS
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'KYCREFERENCETYPE' as column_name, c.hkey, c.KYCREFERENCETYPE as sat_value,
           max(iff(equal_null(c.KYCREFERENCETYPE, e.KYCREFERENCETYPE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.KYCREFERENCETYPE) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.KYCREFERENCETYPE
)
select 'OPUS' as project, 'SAT_PARTY_KYC_REFERENCE' as satellite, 'OPUS_CP_PARTNERS' as record_source, column_name,
       count(*) as keys_compared,
       count_if(src_rows > 0 and matched = 1) as matched,
       count_if(src_rows > 0 and matched = 0) as mismatched,
       count_if(src_rows = 0) as no_source_row,
       array_slice(array_agg(iff(src_rows > 0 and matched = 0, object_construct('hkey', to_varchar(hkey, 'HEX'), 'sat', sat_value, 'src', src_value), null))
                   within group (order by hkey), 0, 3) as mismatch_examples,
       iff(mismatched = 0 and no_source_row = 0, 'PASS', 'FAIL') as status
  from r1
 group by column_name
order by record_source, column_name;



----------------------------------------------------------------------------------------
-- 32. OPUS — SAT_PARTY_ORGANISATION_PROFILE   [Implemented]
-- standard satellite, sat_multi_source; PK PARTY_HKEY; 3 RECORD_SOURCE group(s):
-- stitch_party_organisation_profile (3 tables) [8 col(s)], OPUS_BJAZ_M_KYC_GSTN [1
-- col(s)], OPUS_BJAZ_T_CKYC_PERSONAL_DTLS [0 col(s)]. Stitch groups: expected values are
-- the stitch view recomputed from RAW (same coalesce priority and tie-break), and
-- RECORD_SOURCE (contributing tables) is compared too.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_ORGANISATION_PROFILE
     where regexp_like(RECORD_SOURCE, '^(OPUS_AZBJ_PARTNER_EXTN|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_CP_PARTNERS)(, (OPUS_AZBJ_PARTNER_EXTN|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_CP_PARTNERS))*$')
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(ANNUALTURNOVER) as ANNUALTURNOVER,
           to_varchar(DATEOFINCORPORATION) as DATEOFINCORPORATION,
           to_varchar(GROUPNAME) as GROUPNAME,
           to_varchar(INDUSTRYDESCRIPTION) as INDUSTRYDESCRIPTION,
           to_varchar(LEGALCONSTITUTIONTYPE) as LEGALCONSTITUTIONTYPE,
           to_varchar(MSMEINDICATOR) as MSMEINDICATOR,
           to_varchar(PAIDUPCAPITAL) as PAIDUPCAPITAL,
           to_varchar(PARENTENTITYNAME) as PARENTENTITYNAME,
           RECORD_SOURCE as RECORD_SOURCE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_ORGANISATION_PROFILE
     where regexp_like(RECORD_SOURCE, '^(OPUS_AZBJ_PARTNER_EXTN|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_CP_PARTNERS)(, (OPUS_AZBJ_PARTNER_EXTN|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_CP_PARTNERS))*$')
       and PARTY_HKEY in (select hkey from s1)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
g1_t0 as (  -- stitch source OPUS_AZBJ_PARTNER_EXTN
    select distinct (nullif(trim("PART_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("GLOBAL_CO_NAME"::varchar), '')))), '') as groupname,
           nullif(trim(to_varchar(("INDUSTRY"::number))), '') as industrydescription,
           nullif(trim(to_varchar((nullif(trim("MSME_FLAG"::varchar), '')))), '') as msmeindicator,
           nullif(trim(to_varchar(("PAIDUP_CAPITAL"::number))), '') as paidupcapital,
           nullif(trim(to_varchar((nullif(trim("PARENT_CO"::varchar), '')))), '') as parententityname,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN
     where (nullif(trim("PART_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PART_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t2 as (  -- stitch source OPUS_BJAZ_CLM_SUPP_EXTN
    select distinct (nullif(trim("PARTNER_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("ANN_TURNOVER"::varchar), '')))), '') as annualturnover,
           nullif(trim(to_varchar((nullif(trim("ESTABLISH_YEAR"::varchar), '')))), '') as dateofincorporation,
           nullif(trim(to_varchar((nullif(trim("MSME_CLASS"::varchar), '')))), '') as msmeindicator,
           nullif(trim(to_varchar((nullif(trim("PARENT_CO_NAME"::varchar), '')))), '') as parententityname,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CLM_SUPP_EXTN
     where (nullif(trim("PARTNER_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PARTNER_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t4 as (  -- stitch source OPUS_CP_PARTNERS
    select distinct (nullif(trim("PART_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("LEGAL_FORM"::varchar), '')))), '') as legalconstitutiontype,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.CP_PARTNERS
     where (nullif(trim("PART_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PART_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
k1 as (
    select parent_bk from g1_t0
    union
    select parent_bk from g1_t2
    union
    select parent_bk from g1_t4
),
st1 as (  -- stitch_party_organisation_profile recomputed from RAW (same coalesce / priority as the stitch macro)
    select ak.parent_bk,
           g1_t2.annualturnover as annualturnover,
           g1_t2.dateofincorporation as dateofincorporation,
           g1_t0.groupname as groupname,
           g1_t0.industrydescription as industrydescription,
           g1_t4.legalconstitutiontype as legalconstitutiontype,
           coalesce(g1_t0.msmeindicator, g1_t2.msmeindicator) as msmeindicator,
           g1_t0.paidupcapital as paidupcapital,
           coalesce(g1_t0.parententityname, g1_t2.parententityname) as parententityname,
           array_to_string(array_construct_compact(
               case when g1_t0.parent_bk is not null then 'OPUS_AZBJ_PARTNER_EXTN' end,
               case when g1_t2.parent_bk is not null then 'OPUS_BJAZ_CLM_SUPP_EXTN' end,
               case when g1_t4.parent_bk is not null then 'OPUS_CP_PARTNERS' end
           ), ', ') as record_source,
           greatest_ignore_nulls(g1_t0.inc_job_updated_at, g1_t2.inc_job_updated_at, g1_t4.inc_job_updated_at) as inc_job_updated_at
      from k1 ak
      left join g1_t0 on g1_t0.parent_bk = ak.parent_bk
      left join g1_t2 on g1_t2.parent_bk = ak.parent_bk
      left join g1_t4 on g1_t4.parent_bk = ak.parent_bk
    qualify row_number() over (partition by ak.parent_bk order by g1_t0.groupname nulls last, g1_t0.industrydescription nulls last, g1_t0.msmeindicator nulls last, g1_t0.paidupcapital nulls last, g1_t0.parententityname nulls last, g1_t2.annualturnover nulls last, g1_t2.dateofincorporation nulls last, g1_t2.msmeindicator nulls last, g1_t2.parententityname nulls last, g1_t4.legalconstitutiontype nulls last) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stitch_party_organisation_profile
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || st.parent_bk AS VARCHAR))), '')) as hkey,
               st.inc_job_updated_at as ldts,
               to_varchar(st.annualturnover) as ANNUALTURNOVER,
               to_varchar(st.dateofincorporation) as DATEOFINCORPORATION,
               to_varchar(st.groupname) as GROUPNAME,
               to_varchar(st.industrydescription) as INDUSTRYDESCRIPTION,
               to_varchar(st.legalconstitutiontype) as LEGALCONSTITUTIONTYPE,
               to_varchar(st.msmeindicator) as MSMEINDICATOR,
               to_varchar(st.paidupcapital) as PAIDUPCAPITAL,
               to_varchar(st.parententityname) as PARENTENTITYNAME,
               st.record_source as RECORD_SOURCE
          from st1 st
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'ANNUALTURNOVER' as column_name, c.hkey, c.ANNUALTURNOVER as sat_value,
           max(iff(equal_null(c.ANNUALTURNOVER, e.ANNUALTURNOVER), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.ANNUALTURNOVER) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.ANNUALTURNOVER
    union all
    select 'DATEOFINCORPORATION' as column_name, c.hkey, c.DATEOFINCORPORATION as sat_value,
           max(iff(equal_null(c.DATEOFINCORPORATION, e.DATEOFINCORPORATION), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.DATEOFINCORPORATION) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.DATEOFINCORPORATION
    union all
    select 'GROUPNAME' as column_name, c.hkey, c.GROUPNAME as sat_value,
           max(iff(equal_null(c.GROUPNAME, e.GROUPNAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.GROUPNAME) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.GROUPNAME
    union all
    select 'INDUSTRYDESCRIPTION' as column_name, c.hkey, c.INDUSTRYDESCRIPTION as sat_value,
           max(iff(equal_null(c.INDUSTRYDESCRIPTION, e.INDUSTRYDESCRIPTION), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.INDUSTRYDESCRIPTION) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.INDUSTRYDESCRIPTION
    union all
    select 'LEGALCONSTITUTIONTYPE' as column_name, c.hkey, c.LEGALCONSTITUTIONTYPE as sat_value,
           max(iff(equal_null(c.LEGALCONSTITUTIONTYPE, e.LEGALCONSTITUTIONTYPE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.LEGALCONSTITUTIONTYPE) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.LEGALCONSTITUTIONTYPE
    union all
    select 'MSMEINDICATOR' as column_name, c.hkey, c.MSMEINDICATOR as sat_value,
           max(iff(equal_null(c.MSMEINDICATOR, e.MSMEINDICATOR), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.MSMEINDICATOR) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.MSMEINDICATOR
    union all
    select 'PAIDUPCAPITAL' as column_name, c.hkey, c.PAIDUPCAPITAL as sat_value,
           max(iff(equal_null(c.PAIDUPCAPITAL, e.PAIDUPCAPITAL), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.PAIDUPCAPITAL) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.PAIDUPCAPITAL
    union all
